    [0, 13], [13, 26], [26, 39], [39, 52]
];

const counts = ['P', 'K', 'H', 'T'];

let missing = [];
let duplicate = false;
s.split('').forEach(s => {
    if (!s) return;
    if (duplicate) {
        duplicate = false;
    } else if (s.match(/[HKPT][1-9][0-9]?[0-9]?/)) {
        missing.push(52 - suits[counts.indexOf(s.charAt(0))][1]);
    } else {
        missing.push(0);
    }
});

if (missing.indexOf(0) != -1) {
    missing = [-1, -1, -1, -1];
}

return missing;
