def filter_edges(edges):
    uniques = set()

    for u, v, _ in edges:
        unique_repr = tostr(u) + tostr(v)
        if unique_repr not in uniques:
            uniques.add(unique_repr)
            yield u, v, _

def filter_vertices(n, edges):
    permutation = list(range(1, n + 1))
    for seq in permutations(permutation):
        yield from filter_edges(zip(edge[::2] for edge in edges), zip(edge[::2], edge[::2], seq))

